        provider_type=provider_type,
        name="Default",
        endpoint_url=settings.s3_endpoint_url or "",
        region=settings.s3_region or "us-east-1",
        bucket=settings.s3_bucket_name,
        access_key_encrypted=settings.s3_access_key_encrypted or "",
