    settings.s3_bucket_name = connection.bucket
    settings.s3_access_key_encrypted = connection.access_key_encrypted
    settings.s3_secret_key_encrypted = connection.secret_key_encrypted
    settings.s3_use_ssl = connection.use_ssl
    settings.s3_path_style = connection.path_style
    settings.s3_enabled = connection.enabled
    settings.s3_last_tested_at = connection.last_tested_at
